1	<!DOCTYPE html>
2	<html lang="en" data-theme="dark">
3	<head>
4	  <meta charset="UTF-8">
5	  <meta name="viewport" content="width=device-width, initial-scale=1.0, viewport-fit=cover">
6	  <title>Project Entry — Schema & Table Template Architect</title>
7	  <link rel="preconnect" href="https://fonts.googleapis.com">
8	  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
9	  <link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=IBM+Plex+Sans:wght@400;500;600;700&family=IBM+Plex+Mono:wght@400;500;600&display=swap">
10	
11	  <style>
12	    /* ========================================================================
13	       DESIGN SYSTEM TOKENS
14	       ======================================================================== */
15	    :root {
16	      --bg-canvas:      #0a0908;
17	      --bg-card:        #15110d;
18	      --bg-card-hover:  #1f1813;
19	      --bg-input:       #1c1611;
20	      --bg-input-focus: #28201a;
21	      --bg-row-hover:   #1a1410;
22	      --bg-row-active:  #1f1a0f;
23	
24	      --text-primary:   #fefdfb;
25	      --text-secondary: #e8ddd0;
26	      --text-tertiary:  #8f7f6e;
27	      --text-dim:       #6a5d4f;
28	
29	      --border-light:   #3a2d23;
30	      --border-mid:     #4d3d30;
31	      --border-table:   #2a201a;
32	
33	      --accent:         #ff9e1b;
34	      --accent-hover:   #ffb03a;
35	      --accent-glow:    rgba(255, 158, 27, 0.3);
36	      --accent-bg:      rgba(255, 158, 27, 0.12);
37	
38	      --success:  #10b981;
39	      --warning:  #f59e0b;
40	      --danger:   #f43f5e;
41	
42	      /* Type category colors */
43	      --c-pk:      #38bdf8;
44	      --c-text:    #10b981;
45	      --c-scalar:  #f59e0b;
46	      --c-boolean: #a78bfa;
47	      --c-enum:    #f43f5e;
48	      --c-rel:     #ff9e1b;
49	
50	      --font-display: "IBM Plex Sans", system-ui, sans-serif;
51	      --font-body:    "IBM Plex Sans", system-ui, sans-serif;
52	      --font-mono:    "IBM Plex Mono", monospace;
53	      --base-font-size: 15px;
54	
55	      --gap-xs: 0.5rem;
56	      --gap-sm: 0.75rem;
57	      --gap-md: 1.25rem;
58	      --gap-lg: 2rem;
59	      --gap-xl: 3rem;
60	
61	      --radius-sm: 6px;
62	      --radius-md: 8px;
63	      --radius-lg: 12px;
64	
65	      --input-height: 42px;
66	
67	      --sidebar-width: 400px;
68	      --sidebar-anim: 220ms cubic-bezier(0.16, 1, 0.3, 1);
69	
70	      color-scheme: dark;
71	    }
72	
73	    :root[data-theme="light"] {
74	      --bg-canvas:      #faf8f5;
75	      --bg-card:        #fff8f3;
76	      --bg-card-hover:  #fff0e8;
77	      --bg-input:       #f5ede5;
78	      --bg-input-focus: #fff8f3;
79	      --bg-row-hover:   #fdf4ec;
80	      --bg-row-active:  #fff3e0;
81	
82	      --text-primary:   #18130e;
83	      --text-secondary: #382f26;
84	      --text-tertiary:  #6b5a49;
85	      --text-dim:       #9e8c79;
86	
87	      --border-light:   #e8dccf;
88	      --border-mid:     #d9cabc;
89	      --border-table:   #ede4da;
90	
91	      --accent:         #d97706;
92	      --accent-hover:   #b45309;
93	      --accent-bg:      rgba(217, 119, 6, 0.10);
94	
95	      color-scheme: light;
96	    }
97	
98	    @media (prefers-color-scheme: light) {
99	      :root:not([data-theme="dark"]) {
100	        --bg-canvas:      #faf8f5;
101	        --bg-card:        #fff8f3;
102	        --bg-card-hover:  #fff0e8;
103	        --bg-input:       #f5ede5;
104	        --bg-input-focus: #fff8f3;
105	        --bg-row-hover:   #fdf4ec;
106	        --bg-row-active:  #fff3e0;
107	        --text-primary:   #18130e;
108	        --text-secondary: #382f26;
109	        --text-tertiary:  #6b5a49;
110	        --text-dim:       #9e8c79;
111	        --border-light:   #e8dccf;
112	        --border-mid:     #d9cabc;
113	        --border-table:   #ede4da;
114	        --accent:         #d97706;
115	        --accent-hover:   #b45309;
116	        --accent-bg:      rgba(217, 119, 6, 0.10);
117	        color-scheme: light;
118	      }
119	    }
120	
121	    /* ========================================================================
122	       RESET
123	       ======================================================================== */
124	    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
125	    html, body { height: 100%; }
126	
127	    body {
128	      background: var(--bg-canvas);
129	      color: var(--text-secondary);
130	      font: var(--base-font-size) var(--font-body);
131	      line-height: 1.5;
132	      overflow-x: hidden;
133	    }
134	
135	    /* ========================================================================
136	       APP SHELL
137	       ======================================================================== */
138	    .app-shell {
139	      display: flex;
140	      flex-direction: column;
141	      height: 100vh;
142	      overflow: hidden;
143	    }
144	
145	    /* ========================================================================
146	       HEADER
147	       ======================================================================== */
148	    .app-header {
149	      flex-shrink: 0;
150	      background: var(--bg-card);
151	      border-bottom: 1px solid var(--border-light);
152	      padding: 0.75rem 1.5rem;
153	      display: flex;
154	      align-items: center;
155	      gap: 1.25rem;
156	      flex-wrap: wrap;
157	    }
158	
159	    .app-title {
160	      font: 700 1.35rem var(--font-display);
161	      color: var(--text-primary);
162	      display: flex;
163	      align-items: center;
164	      gap: 0.6rem;
165	      white-space: nowrap;
166	    }
167	
168	    .badge {
169	      font: 600 0.72rem var(--font-mono);
170	      color: var(--accent);
171	      background: var(--accent-bg);
172	      border: 1px solid var(--accent);
173	      padding: 0.2rem 0.55rem;
174	      border-radius: var(--radius-sm);
175	      text-transform: uppercase;
176	      letter-spacing: 0.06em;
177	    }
178	
179	    .header-divider {
180	      width: 1px;
181	      height: 20px;
182	      background: var(--border-mid);
183	      flex-shrink: 0;
184	    }
185	
186	    /* Table tabs */
187	    .table-tabs {
188	      display: flex;
189	      gap: 0.25rem;
190	      flex: 1;
191	      flex-wrap: wrap;
192	    }
193	
194	    .tab-btn {
195	      padding: 0.4rem 0.9rem;
196	      font: 500 13px var(--font-body);
197	      background: transparent;
198	      border: 1px solid transparent;
199	      border-radius: var(--radius-sm);
200	      color: var(--text-tertiary);
201	      cursor: pointer;
202	      transition: all 0.12s ease;
203	      display: flex;
204	      align-items: center;
205	      gap: 0.4rem;
206	      outline: none;
207	    }
208	
209	    .tab-btn:hover {
210	      background: var(--bg-input);
211	      color: var(--text-secondary);
212	      border-color: var(--border-light);
213	    }
214	
215	    .tab-btn.active {
216	      background: var(--accent-bg);
217	      border-color: var(--accent);
218	      color: var(--accent);
219	      font-weight: 600;
220	    }
221	
222	    .tab-btn.new-table {
223	      border-style: dashed;
224	      border-color: var(--border-mid);
225	      color: var(--text-dim);
226	    }
227	
228	    .tab-btn.new-table:hover {
229	      border-color: var(--accent);
230	      color: var(--accent);
231	      background: var(--accent-bg);
232	    }
233	
234	    /* Header actions */
235	    .header-actions {
236	      display: flex;
237	      gap: 0.5rem;
238	      flex-shrink: 0;
239	    }
240	
241	    /* ========================================================================
242	       BUTTONS
243	       ======================================================================== */
244	    button { font: inherit; cursor: pointer; border: none; outline: none; transition: all 0.12s ease; border-radius: var(--radius-md); }
245	
246	    .btn {
247	      height: 36px;
248	      padding: 0 1rem;
249	      font-weight: 600;
250	      font-size: 13px;
251	      display: inline-flex;
252	      align-items: center;
253	      gap: 0.5rem;
254	      background: var(--bg-input);
255	      border: 1px solid var(--border-light);
256	      color: var(--text-secondary);
257	      border-radius: var(--radius-md);
258	    }
259	
260	    .btn:hover {
261	      background: var(--bg-card-hover);
262	      border-color: var(--border-mid);
263	      color: var(--text-primary);
264	    }
265	
266	    .btn.primary {
267	      background: var(--accent);
268	      border-color: var(--accent);
269	      color: #0a0908;
270	      font-weight: 700;
271	    }
272	
273	    .btn.primary:hover { background: var(--accent-hover); border-color: var(--accent-hover); }
274	
275	    .btn.danger {
276	      background: rgba(244, 63, 94, 0.1);
277	      border-color: rgba(244, 63, 94, 0.4);
278	      color: var(--danger);
279	    }
280	
281	    .btn.danger:hover {
282	      background: rgba(244, 63, 94, 0.2);
283	      border-color: var(--danger);
284	    }
285	
286	    .btn.ghost {
287	      background: transparent;
288	      border-color: transparent;
289	      color: var(--text-tertiary);
290	    }
291	
292	    .btn.ghost:hover { background: var(--bg-input); color: var(--text-secondary); }
293	
294	    /* Server Status Indicator */
295	    .status-badge {
296	      display: inline-flex;
297	      align-items: center;
298	      gap: 0.45rem;
299	      font: 500 11.5px var(--font-mono);
300	      color: var(--text-tertiary);
301	      background: var(--bg-input);
302	      border: 1px solid var(--border-light);
303	      padding: 0.25rem 0.65rem;
304	      border-radius: var(--radius-sm);
305	    }
306	    .status-dot {
307	      width: 7px;
308	      height: 7px;
309	      border-radius: 50%;
310	      background: var(--success);
311	      box-shadow: 0 0 6px var(--success);
312	      flex-shrink: 0;
313	    }
314	    .status-dot.offline {
315	      background: var(--danger);
316	      box-shadow: 0 0 6px var(--danger);
317	    }
318	
319	    .btn.sm { height: 30px; padding: 0 0.7rem; font-size: 12px; }
320	    .btn.icon-only { width: 36px; padding: 0; justify-content: center; }
321	    .btn.icon-only.sm { width: 30px; }
322	
323	    /* ========================================================================
324	       TOOLBAR (below header, above table) — single filter row
325	       ======================================================================== */
326	    .toolbar {
327	      flex-shrink: 0;
328	      background: var(--bg-canvas);
329	      border-bottom: 1px solid var(--border-table);
330	      display: flex;
331	      flex-direction: column;
332	    }
333	
334	    /* Filter bar */
335	    .toolbar-row {
336	      padding: 0.45rem 1.25rem;
337	      display: flex;
338	      align-items: center;
339	      gap: 0.5rem;
340	    }
341	
342	    .toolbar-label {
343	      font: 600 10px var(--font-mono);
344	      color: var(--text-dim);
345	      text-transform: uppercase;
346	      letter-spacing: 0.07em;
347	      white-space: nowrap;
348	      flex-shrink: 0;
349	    }
350	
351	    .toolbar-divider {
352	      width: 1px;
353	      height: 14px;
354	      background: var(--border-light);
355	      flex-shrink: 0;
356	    }
357	
358	    /* Filter buttons in toolbar */
359	    .filter-btn {
360	      padding: 0.3rem 0.7rem;
361	      font: 500 12px var(--font-body);
362	      background: transparent;
363	      border: 1px solid transparent;
364	      border-radius: var(--radius-sm);
365	      color: var(--text-tertiary);
366	      cursor: pointer;
367	      transition: all 0.12s ease;
368	    }
369	
370	    .filter-btn:hover {
371	      background: var(--bg-input);
372	      color: var(--text-secondary);
373	    }
374	
375	    .filter-btn.active {
376	      background: var(--accent-bg);
377	      border-color: var(--accent);
378	      color: var(--accent);
379	      font-weight: 600;
380	    }
381	
382	    /* Notion-style draggable table rows */
383	    .notion-table tbody tr.draggable {
384	      cursor: grab;
385	      position: relative;
386	      user-select: none;
387	      touch-action: none;
388	    }
389	
390	    .notion-table tbody tr.draggable:active {
391	      cursor: grabbing;
392	    }
393	
394	    .notion-table tbody tr.draggable.is-dragging {
395	      position: fixed;
396	      z-index: 9999;
397	      cursor: grabbing !important;
398	      opacity: 0.95;
399	      background: var(--bg-card-hover);
400	      border: 1px solid var(--accent);
401	      box-shadow: 0 8px 24px rgba(0,0,0,0.4), 0 0 0 2px var(--accent);
402	      pointer-events: none;
403	      transform-origin: top left;
404	    }
405	
406	    .row-placeholder {
407	      background: var(--accent-bg);
408	      border: 2px dashed var(--accent);
409	      pointer-events: none;
410	      height: 44px;
411	    }
412	
413	    .row-placeholder td {
414	      border: none;
415	      background: transparent;
416	    }
417	
418	    /* Drag handle in the number cell */
419	    .td-num .drag-handle {
420	      display: none;
421	      font-size: 12px;
422	      color: var(--text-dim);
423	      letter-spacing: -1px;
424	      cursor: grab;
425	    }
426	
427	    .notion-table tbody tr.draggable:hover .td-num .row-num {
428	      display: none;
429	    }
430	
431	    .notion-table tbody tr.draggable:hover .td-num .drag-handle {
432	      display: inline;
433	    }
434	
435	    /* ========================================================================
436	       WORKSPACE (table + sidebar)
437	       ======================================================================== */
438	    .workspace {
439	      flex: 1;
440	      display: flex;
441	      overflow: hidden;
442	      position: relative;
443	    }
444	
445	    /* ========================================================================
446	       TABLE AREA
447	       ======================================================================== */
448	    .table-area {
449	      flex: 1;
450	      overflow-y: auto;
451	      overflow-x: auto;
452	      padding: 0;
453	      transition: flex 0.22s cubic-bezier(0.16, 1, 0.3, 1);
454	    }
455	
456	    /* Notion-style table */
457	    .notion-table {
458	      width: 100%;
459	      border-collapse: collapse;
460	      table-layout: fixed;
461	    }
462	
463	    /* Smooth hide for slug/sql cells */
464	    .notion-table .col-slug,
465	    .notion-table .col-sql {
466	      transition: opacity 0.18s ease;
467	    }
468	    .sidebar-open .notion-table .col-slug,
469	    .sidebar-open .notion-table .col-sql {
470	      opacity: 0;
471	      pointer-events: none;
472	    }
473	
474	    /* Default column widths (sidebar closed) */
475	    .notion-table colgroup col:nth-child(1) { width: 48px; }
476	    .notion-table colgroup col:nth-child(2) { width: auto; }
477	    .notion-table colgroup col:nth-child(3) { width: 160px; }
478	    .notion-table colgroup col:nth-child(4) { width: 140px; }
479	    .notion-table colgroup col:nth-child(5) { width: 190px; }
480	    .notion-table colgroup col:nth-child(6) { width: 88px; }
481	
482	    /* Sidebar open: hide Slug & SQL columns to free space, keep Name + Type */
483	    .sidebar-open .notion-table colgroup col:nth-child(4) { width: 0; }
484	    .sidebar-open .notion-table colgroup col:nth-child(5) { width: 0; }
485	    .sidebar-open .notion-table colgroup col:nth-child(6) { width: 52px; }
486	    .sidebar-open .notion-table .col-slug { display: none; }
487	    .sidebar-open .notion-table .col-sql  { display: none; }
488	    .sidebar-open .notion-table .th-slug  { display: none; }
489	    .sidebar-open .notion-table .th-sql   { display: none; }
490	
491	    /* Table head */
492	    .notion-table thead th {
493	      padding: 0.55rem 0.75rem;
494	      text-align: left;
495	      font: 600 11px var(--font-mono);
496	      color: var(--text-dim);
497	      text-transform: uppercase;
498	      letter-spacing: 0.06em;
499	      border-bottom: 1px solid var(--border-table);
500	      background: var(--bg-canvas);
501	      white-space: nowrap;
502	      user-select: none;
503	    }
504	
505	    .notion-table thead th:first-child { text-align: center; }
506	
507	    /* Table body rows */
508	    .notion-table tbody tr {
509	      border-bottom: 1px solid var(--border-table);
510	      cursor: pointer;
511	      transition: background 0.1s ease;
512	    }
513	
514	    .notion-table tbody tr:hover:not(.row-add) { background: var(--bg-row-hover); }
515	
516	    .notion-table tbody tr.selected {
517	      background: var(--bg-row-active);
518	      box-shadow: inset 3px 0 0 var(--accent);
519	    }
520	
521	    /* Table cells */
522	    .notion-table tbody td {
523	      padding: 0 0.75rem;
524	      height: 44px;
525	      vertical-align: middle;
526	      border-right: 1px solid var(--border-table);
527	      font-size: 13.5px;
528	    }
529	
530	    .notion-table tbody td:last-child { border-right: none; }
531	
532	    /* Row number cell */
533	    .td-num {
534	      text-align: center;
535	      font: 500 11px var(--font-mono);
536	      color: var(--text-dim);
537	    }
538	
539	    /* Row hover shows drag handle in num cell */
