2108	    const stored = localStorage.getItem('project_entry_schemas');
2109	    if (stored) {
2110	      const parsed = JSON.parse(stored);
2111	      if (parsed && Object.keys(parsed).length > 0) {
2112	        tables = { ...parsed, ...tables };
