2566	/* ============================================================
2567	   NOTION-STYLE ROW DRAG-TO-REORDER (Pointer-based FLIP)
2568	   Each table row represents a column; drag the left edge to reorder
2569	   ============================================================ */
2570	let rowDrag = null;
2571	
2572	function attachRowDragListeners() {
2573	  const rows = document.querySelectorAll('#table-body tr.draggable');
2574	  rows.forEach(row => {
2575	    const tdNum = row.querySelector('.td-num');
2576	    if (tdNum) {
2577	      tdNum.addEventListener('pointerdown', handleRowPointerDown);
2578	    }
2579	  });
2580	}
2581	
2582	function handleRowPointerDown(e) {
2583	  if (e.button !== 0) return;
2584	
2585	  const tdNum = e.currentTarget;
2586	  const row = tdNum.closest('tr.draggable');
2587	  if (!row) return;
2588	
2589	  const fromIdx = Number(row.dataset.idx);
2590	  const tbody = document.getElementById('table-body');
2591	  const rect = row.getBoundingClientRect();
2592	
2593	  row.setPointerCapture(e.pointerId);
2594	
2595	  const placeholder = document.createElement('tr');
2596	  placeholder.className = 'row-placeholder';
2597	  placeholder.innerHTML = '<td colspan="6"></td>';
2598	
2599	  const offsetX = e.clientX - rect.left;
2600	  const offsetY = e.clientY - rect.top;
2601	
2602	  rowDrag = {
2603	    row, tdNum, fromIdx, tbody, placeholder, offsetX, offsetY, rect,
2604	    isDragging: false, startX: e.clientX, startY: e.clientY
2605	  };
2606	
2607	  const onMove = (me) => {
2608	    if (!rowDrag) return;
2609	    const dist = Math.hypot(me.clientX - rowDrag.startX, me.clientY - rowDrag.startY);
2610	
2611	    if (!rowDrag.isDragging && dist > 5) {
2612	      rowDrag.isDragging = true;
2613	      row.parentNode.insertBefore(placeholder, row);
2614	      row.classList.add('is-dragging');
2615	      row.style.width = `${rect.width}px`;
2616	      row.style.height = `${rect.height}px`;
2617	    }
2618	
2619	    if (rowDrag.isDragging) {
2620	      row.style.left = `${me.clientX - offsetX}px`;
2621	      row.style.top = `${me.clientY - offsetY}px`;
2622	      updateRowPlacementFLIP(me.clientY);
2623	    }
2624	  };
2625	
2626	  const onUp = () => {
2627	    window.removeEventListener('pointermove', onMove);
2628	    window.removeEventListener('pointerup', onUp);
2629	    try { row.releasePointerCapture(e.pointerId); } catch (_) {}
2630	
2631	    if (!rowDrag.isDragging) { rowDrag = null; return; }
2632	
2633	    const targetRect = placeholder.getBoundingClientRect();
2634	    const currentTop = parseFloat(row.style.top);
2635	    const dy = targetRect.top - currentTop;
2636	
2637	    row.style.transition = 'transform 0.22s cubic-bezier(0.16,1,0.3,1)';
2638	    row.style.transform = `translateY(${dy}px)`;
2639	
2640	    setTimeout(() => {
2641	      const allRows = [...tbody.querySelectorAll('tr.draggable')];
2642	      const toIdx = allRows.indexOf(placeholder);
2643	
2644	      row.classList.remove('is-dragging');
2645	      ['position','left','top','width','height','transform','transition']
2646	        .forEach(p => row.style[p] = '');
2647	
2648	      if (placeholder.parentNode) placeholder.parentNode.removeChild(placeholder);
2649	
2650	      if (toIdx !== -1 && toIdx !== rowDrag.fromIdx) {
2651	        const cols = tables[activeTable].columns;
2652	        const [movedCol] = cols.splice(rowDrag.fromIdx, 1);
2653	        cols.splice(toIdx, 0, movedCol);
2654	
2655	        if (activeColIdx !== null) {
2656	          if (activeColIdx === rowDrag.fromIdx) activeColIdx = toIdx;
2657	          else if (rowDrag.fromIdx < toIdx && activeColIdx > rowDrag.fromIdx && activeColIdx <= toIdx) activeColIdx--;
2658	          else if (rowDrag.fromIdx > toIdx && activeColIdx >= toIdx && activeColIdx < rowDrag.fromIdx) activeColIdx++;
2659	        }
2660	
2661	        renderTable();
2662	        if (activeColIdx !== null) { openSidebar(); populateSidebar(); }
2663	        showToast(`Reordered: ${movedCol.name}`);
2664	      }
2665	      rowDrag = null;
2666	    }, 220);
2667	  };
2668	
2669	  window.addEventListener('pointermove', onMove, { passive: true });
2670	  window.addEventListener('pointerup', onUp);
2671	}
2672	
2673	function updateRowPlacementFLIP(pointerY) {
2674	  if (!rowDrag) return;
2675	
2676	  const { row, tbody, placeholder } = rowDrag;
2677	  const allRows = [...tbody.querySelectorAll('tr.draggable:not(.is-dragging)')];
2678	  let target = null;
2679	
2680	  for (const otherRow of allRows) {
2681	    const box = otherRow.getBoundingClientRect();
2682	    if (pointerY < box.top + box.height / 2) {
2683	      target = otherRow;
2684	      break;
2685	    }
2686	  }
2687	
2688	  const curr = placeholder.nextElementSibling === row ? row.nextElementSibling : placeholder.nextElementSibling;
2689	  if (curr === target) return;
2690	
2691	  const firstPos = new Map();
2692	  allRows.forEach(r => firstPos.set(r, r.getBoundingClientRect()));
2693	
2694	  if (target) tbody.insertBefore(placeholder, target);
2695	  else tbody.appendChild(placeholder);
2696	
2697	  allRows.forEach(r => {
2698	    const first = firstPos.get(r);
2699	    const last = r.getBoundingClientRect();
2700	    const dy = first.top - last.top;
2701	    if (dy !== 0) {
2702	      r.style.transition = 'none';
2703	      r.style.transform = `translateY(${dy}px)`;
2704	      r.offsetHeight;
2705	      r.style.transition = 'transform 0.22s cubic-bezier(0.2,0,0,1)';
2706	      r.style.transform = '';
2707	    }
2708	  });
2709	}
