2714	function generateSQL(table) {
2715	  if (!table) return '-- No table';
2716	  const lines = [`CREATE TABLE IF NOT EXISTS ${table.table_name} (`];
2717	  const cols = table.columns.map(col => {
2718	    const ft = FIELD_TYPES[col.type];
2719	    return `    ${(col.slug || col.name).padEnd(22)} ${ft.sql}`;
2720	  });
2721	  lines.push(cols.join(',\n'));
2722	  lines.push(');');
2723	  return lines.join('\n');
2724	}
