2833	async function ensureRecordsLoaded(tableName) {
2834	  if (tableRecords[tableName]) return;
2835	
2836	  // Try fetching real SQLite records via server
2837	  try {
2838	    const res = await fetch(`${API_BASE}/api/records/${encodeURIComponent(tableName)}`);
2839	    if (res.ok) {
2840	      const data = await res.json();
2841	      if (data.success && Array.isArray(data.records)) {
2842	        tableRecords[tableName] = data.records;
2843	        if (currentViewMode === 'data') renderDataWorkspace();
2844	        return;
2845	      }
2846	    }
2847	  } catch (e) { }
2848	
2849	  // Fallback: localStorage
2850	  try {
2851	    const local = localStorage.getItem(`records_${tableName}`);
2852	    if (local) {
2853	      tableRecords[tableName] = JSON.parse(local);
2854	      if (currentViewMode === 'data') renderDataWorkspace();
2855	      return;
2856	    }
2857	  } catch (e) { }
2858	
2859	  // Fallback: Rose Mock Records
2860	  if (typeof MOCK_RECORDS !== 'undefined' && MOCK_RECORDS[tableName]) {
2861	    tableRecords[tableName] = JSON.parse(JSON.stringify(MOCK_RECORDS[tableName]));
2862	    if (currentViewMode === 'data') renderDataWorkspace();
2863	    return;
2864	  }
2865	
2866	  // Initialize empty or default
2867	  tableRecords[tableName] = [];
2868	  if (currentViewMode === 'data') renderDataWorkspace();
2869	}
