3080	function generateHexId(prefix) {
3081	  const p = (prefix || 'ROW').substring(0, 4).toUpperCase();
3082	  const hex = Array.from(crypto.getRandomValues(new Uint8Array(4)))
3083	    .map(b => b.toString(16).padStart(2, '0')).join('');
3084	  return `${p}_${hex}`;
3085	}
