}

.sidebar-col-label .col-title {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.sidebar-nav {
  display: flex;
  gap: 0.25rem;
  align-items: center;
}

/* Sidebar tabs */
.sidebar-tabs {
  display: flex;
  gap: 0.25rem;
}

.stab-btn {
  padding: 0.3rem 0.7rem;
  font: 600 11px var(--font-mono);
  background: transparent;
  border: 1px solid transparent;
  border-radius: var(--radius-sm);
  color: var(--text-dim);
  cursor: pointer;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  transition: all 0.12s ease;
}

.stab-btn:hover { background: var(--bg-input); color: var(--text-secondary); }

.stab-btn.active {
  background: var(--accent-bg);
  border-color: var(--accent);
  color: var(--accent);
}

/* Sidebar body */
.sidebar-body {
  flex: 1;
  overflow-y: auto;
  padding: 1.25rem;
  display: flex;
  flex-direction: column;
  gap: 1.25rem;
}

/* Sidebar panels */
.sidebar-panel { display: none; flex-direction: column; gap: 1.25rem; }
.sidebar-panel.active { display: flex; }

/* Field groups */
.field-group {
  display: flex;
  flex-direction: column;
  gap: 0.4rem;
}

.field-label {
  font: 600 11px var(--font-mono);
  color: var(--text-tertiary);
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.field-hint {
  font: 400 11px var(--font-body);
  color: var(--text-dim);
  text-transform: none;
  letter-spacing: 0;
}

