/* Notion-style draggable table rows */
.notion-table tbody tr.draggable {
  cursor: grab;
  position: relative;
  user-select: none;
  touch-action: none;
}

.notion-table tbody tr.draggable:active {
  cursor: grabbing;
}

.notion-table tbody tr.draggable.is-dragging {
  position: fixed;
  z-index: 9999;
  cursor: grabbing !important;
  opacity: 0.95;
  background: var(--bg-card-hover);
  border: 1px solid var(--accent);
  box-shadow: 0 8px 24px rgba(0,0,0,0.4), 0 0 0 2px var(--accent);
  pointer-events: none;
  transform-origin: top left;
}

.row-placeholder {
  background: var(--accent-bg);
  border: 2px dashed var(--accent);
  pointer-events: none;
  height: 44px;
}

.row-placeholder td {
  border: none;
  background: transparent;
}

/* Drag handle in the number cell */
.td-num .drag-handle {
  display: none;
  font-size: 12px;
  color: var(--text-dim);
  letter-spacing: -1px;
  cursor: grab;
}

.notion-table tbody tr.draggable:hover .td-num .row-num {
  display: none;
}

.notion-table tbody tr.draggable:hover .td-num .drag-handle {
  display: inline;
}

