/* Slug & SQL cells */
.td-slug {
  font: 500 12px var(--font-mono);
  color: var(--text-tertiary);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.td-sql {
  font: 400 11.5px var(--font-mono);
  color: var(--text-dim);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* Action cell */
.td-actions {
  display: flex;
  align-items: center;
  gap: 0.2rem;
  justify-content: flex-end;
  opacity: 0;
  transition: opacity 0.1s ease;
}

.notion-table tbody tr:hover .td-actions { opacity: 1; }

/* Add row strip */
.row-add td {
  padding: 0.5rem 0.75rem;
  cursor: default;
}

.row-add:hover { background: transparent !important; }

.add-field-strip {
  display: flex;
  gap: 0.4rem;
  flex-wrap: wrap;
  align-items: center;
  padding: 0.4rem 0;
}

.add-chip {
  display: inline-flex;
  align-items: center;
  gap: 0.3rem;
  padding: 0.3rem 0.65rem;
  background: var(--bg-input);
  border: 1px solid var(--border-light);
  border-radius: 4px;
  font: 500 12px var(--font-body);
  color: var(--text-tertiary);
  cursor: pointer;
  transition: all 0.12s ease;
}

.add-chip:hover {
  background: var(--bg-card-hover);
  border-color: var(--accent);
  color: var(--accent);
}

.table-empty {
  padding: 3rem;
  text-align: center;
  color: var(--text-dim);
  font-size: 14px;
}

/* Draggable Table Rows (FLIP reordering) */
.notion-table tbody tr.draggable {
  cursor: grab;
  position: relative;
  user-select: none;
  touch-action: none;
}

.notion-table tbody tr.draggable:active {
  cursor: grabbing;
}

.notion-table tbody tr.draggable.is-dragging {
  position: fixed;
  z-index: 9999;
  cursor: grabbing !important;
  opacity: 0.95;
  background: var(--bg-card-hover);
  border: 1px solid var(--accent);
  box-shadow: 0 8px 24px rgba(0,0,0,0.4), 0 0 0 2px var(--accent);
  pointer-events: none;
  transform-origin: top left;
}

.row-placeholder {
  background: var(--accent-bg);
  border: 2px dashed var(--accent);
  pointer-events: none;
  height: 44px;
}

.row-placeholder td {
  border: none;
  background: transparent;
}

